#!/bin/bash
set -e
echo '=== DEPLOY parents notif/push ==='
BACKEND=''
for d in \
  "$HOME/kalunga-school/backend" \
  "$HOME/institut-kalunga.net/kalunga-school/backend" \
  "$HOME/public_html/kalunga-school/backend" \
  "$HOME/institut-kalunga.net/backend"
do
  if [ -f "$d/passenger_wsgi.py" ] || [ -d "$d/apps/api" ]; then BACKEND="$d"; break; fi
done
if [ -z "$BACKEND" ]; then
  FOUND=$(find "$HOME" -maxdepth 5 -type f -name 'parents_notifications.py' 2>/dev/null | head -n 1)
  if [ -n "$FOUND" ]; then BACKEND=$(dirname "$(dirname "$(dirname "$FOUND")")"); fi
fi
if [ -z "$BACKEND" ]; then echo 'BACKEND_DIR_NOT_FOUND'; exit 1; fi
cd "$BACKEND"
echo "BACKEND=$PWD"
mkdir -p apps/api tmp
python3 - <<'PY'
import base64, pathlib
notif = base64.b64decode('''''')
push = base64.b64decode('''''')
pathlib.Path('apps/api/parents_notifications.py').write_bytes(notif)
pathlib.Path('apps/api/parents_push.py').write_bytes(push)
print('WROTE parents_notifications.py', len(notif), 'bytes')
print('WROTE parents_push.py', len(push), 'bytes')
PY
touch tmp/restart.txt
touch passenger_wsgi.py 2>/dev/null || true
echo '=== VERIFY ==='
grep -n 'occurred_at\|alerts_v2' apps/api/parents_notifications.py apps/api/parents_push.py | head -n 20
curl -s -o /dev/null -w 'HTTP %{http_code}\n' https://institut-kalunga.net/api/v1/health/ || true
echo DONE